/**
 * Records of completed bulk imports, keyed by `(orgId, importKey)`.
 *
 * A row here is what turns a re-uploaded key into a replay instead of a
 * second batch of issues. Only written once an import has fully succeeded —
 * a refused import never reaches this table, so the same key can be retried.
 */
import { and, eq } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, issueImports } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { toIssueImportIds } from "./_mappers";
import type { IssueId, OrgId, ProjectId } from "@/types/common";

export async function findImport(
  orgId: OrgId,
  importKey: string,
): Promise<readonly IssueId[] | null> {
  const row = getDb()
    .select()
    .from(issueImports)
    .where(
      and(
        orgPredicate(issueImports.orgId, orgId),
        eq(issueImports.importKey, importKey),
      ),
    )
    .get();

  return row ? toIssueImportIds(row) : null;
}

export async function insertImport(
  orgId: OrgId,
  projectId: ProjectId,
  importKey: string,
  issueIds: readonly IssueId[],
): Promise<void> {
  const stamp = toIsoTimestamp(new Date());

  getDb()
    .insert(issueImports)
    .values({
      id: newId(),
      orgId,
      projectId,
      importKey,
      issueIds: JSON.stringify(issueIds),
      createdAt: stamp,
      updatedAt: stamp,
    })
    .run();
}

