/** One row per import: an author, no parent, no estimate, a fixed label set. */
export type ImportIssueRow = {
  readonly title: string;
  readonly description: string | null;
  readonly status: IssueStatus;
  readonly priority: IssuePriority;
  readonly assigneeId: UserId | null;
  readonly labelIds: readonly LabelId[];
  readonly dueAt: IsoTimestamp | null;
};

/**
 * Inserts a whole import batch in one transaction: either every row and its
 * labels land, or none do. Numbers are assigned in file order starting at
 * `startNumber`, so the caller need only compute that once up front.
 */
export async function bulkInsertIssues(
  orgId: OrgId,
  projectId: ProjectId,
  authorId: UserId,
  startNumber: number,
  rows: readonly ImportIssueRow[],
): Promise<readonly Issue[]> {
  const db = getDb();
  const stamp = toIsoTimestamp(new Date());

  return db.transaction((tx) => {
    return rows.map((row, index) => {
      const inserted = tx
        .insert(issues)
        .values({
          id: newId(),
          orgId,
          projectId,
          number: startNumber + index,
          title: row.title,
          description: row.description,
          status: row.status,
          priority: row.priority,
          authorId,
          assigneeId: row.assigneeId,
          parentId: null,
          estimate: null,
          dueAt: row.dueAt,
          startedAt: null,
          completedAt: null,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .returning()
        .get();

      if (row.labelIds.length > 0) {
        tx.insert(issueLabels)
          .values(
            row.labelIds.map((labelId) => ({
              orgId,
              issueId: inserted.id,
              labelId,
            })),
          )
          .run();
      }

      return toIssue(inserted, row.labelIds);
    });
  });
}

