 * the original result and touches nothing.
 */
export async function importIssues(
  actor: Actor,
  input: ImportIssuesInput,
): Promise<IssueImportResult> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  const replayed = await issueImportRepo.findImport(input.orgId, input.importKey);
  if (replayed !== null) {
    const issues = await issueRepo.findIssuesByIds(input.orgId, replayed);
    return {
      importKey: input.importKey,
      projectId: input.projectId,
      issues,
      replayed: true,
    };
  }

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  const used = await issueRepo.countIssues(input.orgId, input.projectId);
  if (wouldExceedLimit(org.plan, "issuesPerProject", used, input.rows.length)) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${project.key}`,
    );
  }

  const verdict = await consumeRateLimit(
    input.orgId,
    ISSUE_CREATE_BUCKET,
    input.rows.length,
  );
  if (!verdict.allowed) {
    throw new Error(
      `Issue creation rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  const assigneeIdByEmail = await resolveAssignees(input.orgId, input.rows);
  const labelIdByName = await resolveLabels(input.orgId, input.rows);
  const startNumber = await issueRepo.nextIssueNumber(
    input.orgId,
    input.projectId,
  );

  const issues = await issueRepo.bulkInsertIssues(
    input.orgId,
    input.projectId,
    actor.userId,
    startNumber,
    input.rows.map((row) => ({
      title: row.title,
      description: row.description,
      status: row.status,
      priority: row.priority,
      assigneeId:
        row.assigneeEmail === null
          ? null
          : (assigneeIdByEmail.get(row.assigneeEmail) ?? null),
      labelIds: [
        ...new Set(row.labels.map((name) => labelIdByName.get(name))),
      ].filter((labelId): labelId is LabelId => labelId !== undefined),
      dueAt: row.dueAt,
    })),
  );

  const issueIds = issues.map((issue) => issue.id);
  await issueImportRepo.insertImport(
    input.orgId,
    input.projectId,
    input.importKey,
    issueIds,
  );

  await emit("issues.imported", {
    ...actorEnvelope(actor),
    projectId: input.projectId,
    importKey: input.importKey,
    issueIds,
  });

  return {
    importKey: input.importKey,
    projectId: input.projectId,
    issues,
    replayed: false,
  };
}

/** Unknown, foreign or removed addresses simply leave the row unassigned. */
async function resolveAssignees(
  orgId: OrgId,
  rows: ImportIssuesInput["rows"],
): Promise<ReadonlyMap<string, UserId>> {
  const emails = new Set(
    rows
      .map((row) => row.assigneeEmail)
      .filter((email): email is string => email !== null),
  );

  const resolved = new Map<string, UserId>();
  for (const email of emails) {
    const member = await memberRepo.findActiveMemberByEmail(orgId, email);
    if (member) resolved.set(email, member.userId);
  }
  return resolved;
}

/** Every label named anywhere in the batch is created at most once. */
async function resolveLabels(
  orgId: OrgId,
  rows: ImportIssuesInput["rows"],
): Promise<ReadonlyMap<string, LabelId>> {
  const names = new Set(rows.flatMap((row) => row.labels));
  const existing = await labelRepo.listLabels(orgId);
  const byName = new Map(existing.map((label) => [label.name, label.id]));

  for (const name of names) {
    if (byName.has(name)) continue;
    const created = await labelRepo.insertLabel({
      orgId,
      name,
      color: "#94a3b8",
      description: null,
    });
    byName.set(name, created.id);
  }

  return byName;
}

