import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { NotFoundError } from "@/server/services/_support";
import { TenantScopeError } from "@/lib/tenant";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import * as labelRepo from "@/server/repositories/label-repository";
import * as usageService from "@/server/services/usage-service";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";

let cleanup: () => void;
let tenant: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("importverify", "growth");
});

afterAll(() => {
  cleanup();
});

function row(overrides: Partial<Record<string, unknown>> = {}) {
  return {
    title: "Imported issue",
    description: null,
    status: "backlog" as const,
    priority: "none" as const,
    assigneeEmail: null,
    labels: [],
    dueAt: null,
    ...overrides,
  };
}

describe("importIssues verification", () => {
  it("imports rows in order, resolves assignee + labels, emits one event, and persists for replay", async () => {
    const received: unknown[] = [];
    const off = subscribe("issues.imported", (p) => received.push(p));

    const memberEmail = `member@importverify.test`;

    try {
      const result = await issueService.importIssues(tenant.actors.member, {
        orgId: tenant.org.id,
        projectId: tenant.project.id,
        importKey: "import-key-001",
        rows: [
          row({ title: "First row", labels: ["bug", "bug"], assigneeEmail: memberEmail }),
          row({ title: "Second row", labels: ["feature"] }),
          row({ title: "Unknown assignee", assigneeEmail: "nobody@nowhere.test" }),
        ],
      });

      expect(result.replayed).toBe(false);
      expect(result.issues.map((i) => i.title)).toEqual([
        "First row",
        "Second row",
        "Unknown assignee",
      ]);
      expect(result.issues[0]!.assigneeId).toBe(tenant.userIds.member);
      expect(result.issues[0]!.labelIds.length).toBe(1);
      expect(result.issues[2]!.assigneeId).toBeNull();

      expect(received).toHaveLength(1);
      expect(received[0]).toMatchObject({
        projectId: tenant.project.id,
        importKey: "import-key-001",
        issueIds: result.issues.map((i) => i.id),
      });

      const labels = await labelRepo.listLabels(tenant.org.id);
      expect(labels.map((l) => l.name).sort()).toEqual(["bug", "feature"]);

      const usage = await usageService.recomputeUsage(tenant.org.id);
      expect(usage.issuesUsed).toBeGreaterThanOrEqual(3);

      // Replay: same key, different rows content — must return original result.
      const replay = await issueService.importIssues(tenant.actors.member, {
        orgId: tenant.org.id,
        projectId: tenant.project.id,
        importKey: "import-key-001",
        rows: [row({ title: "DIFFERENT" })],
      });
      expect(replay.replayed).toBe(true);
      expect(replay.issues.map((i) => i.title)).toEqual([
        "First row",
        "Second row",
        "Unknown assignee",
      ]);
      expect(received).toHaveLength(1); // no new event on replay
    } finally {
      off();
    }
  });

  it("refuses an unknown project with NotFoundError and creates nothing", async () => {
    await expect(
      issueService.importIssues(tenant.actors.member, {
        orgId: tenant.org.id,
        projectId: "01ARZ3NDEKTSV4RRFFQ69G5FAV" as never,
        importKey: "import-key-missing",
        rows: [row()],
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("refuses cross-tenant orgId with TenantScopeError", async () => {
    const other = await createTenant("importverify-other");
    await expect(
      issueService.importIssues(tenant.actors.member, {
        orgId: other.org.id,
        projectId: other.project.id,
        importKey: "import-key-cross",
        rows: [row()],
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });

  it("refuses import into an archived project", async () => {
    const archivable = await createTenant("importverify-archived");
    await projectService.archiveProject(
      archivable.actors.owner,
      archivable.org.id,
      archivable.project.id,
    );

    await expect(
      issueService.importIssues(archivable.actors.member, {
        orgId: archivable.org.id,
        projectId: archivable.project.id,
        importKey: "import-key-archived",
        rows: [row()],
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
  });

  it("refuses when the batch would exceed the plan's per-project issue quota, and the key stays reusable", async () => {
    const quotaTenant = await createTenant("importverify-quota", "free");
    const rows = Array.from({ length: 101 }, (_, i) => row({ title: `Row ${i}` }));

    await expect(
      issueService.importIssues(quotaTenant.actors.member, {
        orgId: quotaTenant.org.id,
        projectId: quotaTenant.project.id,
        importKey: "import-key-quota",
        rows,
      }),
    ).rejects.toThrow(/allows no more issues/);

    const usage = await usageService.recomputeUsage(quotaTenant.org.id);
    expect(usage.issuesUsed).toBe(0);

    // Same key retried with a smaller batch must succeed (key not burned).
    const ok = await issueService.importIssues(quotaTenant.actors.member, {
      orgId: quotaTenant.org.id,
      projectId: quotaTenant.project.id,
      importKey: "import-key-quota",
      rows: [row({ title: "Fits now" })],
    });
    expect(ok.replayed).toBe(false);
    expect(ok.issues).toHaveLength(1);
  });
});

